const converted = Number('abc');

const failed = Number.isNaN(converted);

function getFailed() {
  return failed;
}

function describeValue(value) {
  const converted = Number(value);

  return {
    type: typeof value,
    text: String(value),
    asNumber: Number.isNaN(converted) ? null : converted,
  };
}
